//! FreeANDIY branding: the paper-and-ink look of the light and dark themes, the UI font and the
//! upstream attribution shown in About.

use std::sync::Arc;

use egui::{Color32, Context, FontData, FontDefinitions, FontFamily, Id, TextureHandle, TextureOptions, Ui, Visuals};

use crate::theme::Tokens;

pub const APP_NAME: &str = "FreeANDIY Sheets";
pub const OWNER: &str = "Free Andy Agency";
pub const UPSTREAM_NAME: &str = "GridCraft";

const BLACK: Color32 = Color32::from_rgb(35, 31, 32);
const PAPER: Color32 = Color32::from_rgb(243, 242, 241);
const WHITE: Color32 = Color32::from_rgb(255, 255, 255);
const ROSE: Color32 = Color32::from_rgb(190, 62, 107);
const PINK: Color32 = Color32::from_rgb(234, 153, 153);
const YELLOW: Color32 = Color32::from_rgb(255, 217, 102);

/// `a` blended towards `b` by `t` (0..1), like ink at `t` opacity on paper.
const fn mix(a: Color32, b: Color32, t: f32) -> Color32 {
    Color32::from_rgb(channel(a.r(), b.r(), t), channel(a.g(), b.g(), t), channel(a.b(), b.b(), t))
}

const fn channel(x: u8, y: u8, t: f32) -> u8 {
    (x as f32 + (y as f32 - x as f32) * t + 0.5) as u8
}

/// Light is paper and ink, dark ink and paper: the chrome takes FreeANDIY's colours, the stamp
/// rose marks what is active and selected, the yellow highlighter the selected headers. The grid
/// keeps a white (or black) sheet: cell colours are the workbook's.
pub fn tokens(t: Tokens) -> Tokens {
    if t.dark {
        let ink = |x: f32| mix(BLACK, PAPER, x);
        Tokens {
            window: mix(BLACK, Color32::BLACK, 0.25),
            ribbon: BLACK,
            ribbon_border: ink(0.18),
            text: PAPER,
            text_dim: ink(0.72),
            accent: PINK,
            accent_dark: ROSE,
            accent_soft: mix(BLACK, ROSE, 0.35),
            hover: ink(0.12),
            pressed: ink(0.20),
            separator: ink(0.18),
            header_sel_text: PINK,
            sel_border: PINK,
            sel_fill: Color32::from_rgba_unmultiplied(0xEA, 0x99, 0x99, 0x24),
            tab_bar: mix(BLACK, Color32::BLACK, 0.25),
            tab_active: BLACK,
            status_bar: mix(BLACK, Color32::BLACK, 0.25),
            menu_bg: BLACK,
            ..t
        }
    } else {
        let ink = |x: f32| mix(PAPER, BLACK, x);
        Tokens {
            window: ink(0.04),
            ribbon: PAPER,
            ribbon_border: ink(0.15),
            text: BLACK,
            text_dim: ink(0.70),
            accent: ROSE,
            accent_dark: mix(ROSE, BLACK, 0.25),
            accent_soft: mix(PAPER, ROSE, 0.15),
            hover: ink(0.08),
            pressed: ink(0.15),
            separator: ink(0.15),
            header_sel_bg: mix(PAPER, YELLOW, 0.55),
            header_sel_text: BLACK,
            header_all_bg: mix(PAPER, YELLOW, 0.70),
            sel_fill: Color32::from_rgba_unmultiplied(0xBE, 0x3E, 0x6B, 0x1C),
            sel_border: ROSE,
            tab_bar: ink(0.04),
            tab_active: WHITE,
            status_bar: ink(0.04),
            menu_bg: PAPER,
            ..t
        }
    }
}

/// Flat print look for egui's own surfaces: nearly square windows and menus, no soft shadows.
pub fn visuals(v: &mut Visuals) {
    v.window_corner_radius = egui::CornerRadius::same(2);
    v.menu_corner_radius = egui::CornerRadius::same(2);
    v.popup_shadow = egui::epaint::Shadow::NONE;
    v.window_shadow = egui::epaint::Shadow::NONE;
}

/// The interface font: IBM Plex Sans (SIL Open Font License 1.1; licence in
/// freeandiy/assets/fonts/) ahead of the system UI font, which stays the fallback. Desktop only:
/// the web build keeps its fonts, so the wasm does not grow.
pub fn ui_fonts(fonts: &mut FontDefinitions) {
    #[cfg(not(target_arch = "wasm32"))]
    {
        let faces: [(&str, &str, &'static [u8]); 2] = [
            (crate::theme::UI, "IBMPlexSans", include_bytes!("../../../freeandiy/assets/fonts/IBMPlexSans-Regular.ttf")),
            (crate::theme::UI_BOLD, "IBMPlexSans-SemiBold", include_bytes!("../../../freeandiy/assets/fonts/IBMPlexSans-SemiBold.ttf")),
        ];
        for (role, key, bytes) in faces {
            fonts.font_data.insert(key.to_string(), Arc::new(FontData::from_static(bytes)));
            if let Some(chain) = fonts.families.get_mut(&FontFamily::Name(role.into())) {
                chain.insert(0, key.to_string());
            }
        }
    }
    #[cfg(target_arch = "wasm32")]
    let _ = fonts;
}

/// English, like the rest of upstream's About tab.
const ATTRIBUTION: &str = "{app} is based on the open-source project {upstream} (© ArtCraft Team and contributors, MIT/Apache-2.0). FreeANDIY is not affiliated with the ArtCraft team.";

const SEAL_PNG: &[u8] = include_bytes!("../../../freeandiy/assets/brand/fa-seal-rose.png");

fn seal(ctx: &Context) -> Option<TextureHandle> {
    let id = Id::new("freeandiy-seal");
    if let Some(tex) = ctx.data(|d| d.get_temp::<TextureHandle>(id)) {
        return Some(tex);
    }
    let img = image::load_from_memory_with_format(SEAL_PNG, image::ImageFormat::Png).ok()?.to_rgba8();
    let image = egui::ColorImage::from_rgba_unmultiplied([img.width() as usize, img.height() as usize], img.as_raw());
    let options = TextureOptions { mipmap_mode: Some(egui::TextureFilter::Linear), ..TextureOptions::LINEAR };
    let tex = ctx.load_texture("freeandiy-seal", image, options);
    ctx.data_mut(|d| d.insert_temp(id, tex.clone()));
    Some(tex)
}

/// The About tab's attribution: the Free Andy Agency seal and the upstream credit (MIT/Apache-2.0
/// require keeping the notices; the ArtCraft brand terms allow naming the origin in plain text).
pub fn about_attribution(ui: &mut Ui) {
    let t = Tokens::get(ui.ctx());
    let text = ATTRIBUTION.replace("{app}", APP_NAME).replace("{upstream}", UPSTREAM_NAME);
    ui.horizontal(|ui| {
        if let Some(tex) = seal(ui.ctx()) {
            ui.add(egui::Image::new(&tex).fit_to_exact_size(egui::vec2(48.0, 48.0)));
        }
        ui.vertical(|ui| {
            ui.label(egui::RichText::new(text).small().color(t.text_dim));
            ui.label(egui::RichText::new(format!("© {OWNER}")).small().color(t.text_dim));
        });
    });
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn the_seal_decodes() {
        assert!(seal(&Context::default()).is_some());
    }

    #[test]
    fn light_and_dark_are_paper_and_ink() {
        let (light, dark) = (Tokens::light(), Tokens::dark());
        assert_eq!((light.ribbon, light.text, light.accent), (PAPER, BLACK, ROSE));
        assert_eq!((dark.ribbon, dark.text, dark.accent), (BLACK, PAPER, PINK));
    }
}
